<section id="panel-tamu" role="tabpanel" aria-labelledby="tab-tamu" class="pameran-panel" hidden>
    <p class="notice" id="guest-notice" role="status" hidden></p>
    <div class="pameran-metrics">
        <button type="button" class="kpi blue" data-guest-detail="total" aria-haspopup="dialog"><div><i data-lucide="users" aria-hidden="true"></i><span>Pengunjung tercatat</span></div><strong id="guest-total">-</strong><small>Selama acara &middot; respons valid</small></button>
        <button type="button" class="kpi teal" data-guest-detail="hari_ini" aria-haspopup="dialog"><div><i data-lucide="calendar-days" aria-hidden="true"></i><span>Pengunjung hari ini</span></div><strong id="guest-today">-</strong><small id="guest-today-date">Tanggal hari berjalan (WIB)</small></button>
        <button type="button" class="kpi yellow" data-guest-detail="puas" aria-haspopup="dialog"><div><i data-lucide="smile" aria-hidden="true"></i><span>Puas / sangat puas</span></div><strong id="guest-satisfied">-</strong><small id="guest-average">Penilaian stand</small></button>
        <button type="button" class="kpi teal" data-guest-detail="nusa" aria-haspopup="dialog"><div><i data-lucide="monitor-smartphone" aria-hidden="true"></i><span>Kepuasan NUSA</span></div><strong id="guest-nusa">-</strong><small id="guest-nusa-count">Hanya pengunjung yang menilai</small></button>
    </div>
    <div class="pameran-guest-grid">
        <section class="chart-section"><div class="section-heading"><h2>Kunjungan per hari</h2><div class="heading-actions"><div class="segments" aria-label="Jenis grafik kunjungan"><button type="button" data-guest-chart="bar" aria-pressed="true" title="Grafik batang" aria-label="Grafik batang"><i data-lucide="chart-no-axes-column" aria-hidden="true"></i></button><button type="button" data-guest-chart="line" aria-pressed="false" title="Grafik garis" aria-label="Grafik garis"><i data-lucide="chart-line" aria-hidden="true"></i></button></div><button type="button" class="detail-icon" data-guest-detail="harian" title="Rincian kunjungan per hari" aria-label="Rincian kunjungan per hari"><i data-lucide="expand" aria-hidden="true"></i></button></div></div><div class="chart-area"><canvas id="guest-daily-chart" role="img" aria-label="Grafik kunjungan per hari selama acara"></canvas></div><p class="caption">Jumlah respons valid, bukan hitungan scan atau verifikasi orang unik.</p></section>
        <section class="chart-section"><div class="section-heading"><h2>Kepuasan pengunjung</h2><div class="heading-actions"><span class="tag teal-tag">Stand sekolah</span><button type="button" class="detail-icon" data-guest-detail="kepuasan" title="Rincian kepuasan pengunjung" aria-label="Rincian kepuasan pengunjung"><i data-lucide="expand" aria-hidden="true"></i></button></div></div><div class="chart-area"><canvas id="guest-rating-chart" role="img" aria-label="Grafik distribusi penilaian kepuasan stand"></canvas></div><p class="caption">Netral tidak dihitung sebagai puas.</p></section>
        <section class="lower-section worship-section"><div class="section-heading"><h2><i data-lucide="sparkles" aria-hidden="true"></i>Minat pengunjung</h2><div class="heading-actions"><span class="tag teal-tag" id="guest-interest-page">Hal. 1/1</span><button type="button" class="detail-icon" data-guest-detail="minat" title="Rincian minat pengunjung" aria-label="Rincian minat pengunjung"><i data-lucide="expand" aria-hidden="true"></i></button></div></div><div id="guest-interests" class="pameran-interest-list"><p class="empty">Menunggu data...</p></div><p class="caption">Satu pengunjung dapat memilih lebih dari satu minat.</p></section>
        <section class="lower-section points-section"><div class="section-heading"><h2><i data-lucide="users-round" aria-hidden="true"></i>Pengunjung terbaru</h2><div class="heading-actions"><span class="tag teal-tag" id="guest-recent-count">-</span><button type="button" class="detail-icon" data-guest-detail="terbaru" title="Semua pengunjung terbaru" aria-label="Semua pengunjung terbaru"><i data-lucide="expand" aria-hidden="true"></i></button></div></div><div id="guest-recent" class="pameran-recent"><p class="empty">Menunggu kunjungan...</p></div><p class="caption" id="guest-recent-page">Kunjungan terbaru &middot; pembaruan 3 detik</p></section>
    </div>
</section>
